#!/bin/bash
# ============================================================
# Installer: Psychologist Emotional-Understanding & Counseling Datasets
# Author: Abhay (generated by M365 Copilot)
# Date: 2026-02-04
# ============================================================
set -euo pipefail

ROOT="datasets"
mkdir -p "${ROOT}"
cd "${ROOT}"

echo "=== 🔧 Creating top-level directories ==="
mkdir -p empathetic_dialogues pysdial mentalchat16k medic mh_counseling counselchat ecc logs

log() { echo "[$(date '+%Y-%m-%d %H:%M:%S')] $*" | tee -a "../logs/install.log"; }

# ------------------------------------------------------------
# 1) EmpatheticDialogues (ED)
# Ref: GitHub readme provides the direct tarball link
# ------------------------------------------------------------
log "⬇️ EmpatheticDialogues (ED) ..."
cd empathetic_dialogues
if [ ! -f empatheticdialogues.tar.gz ]; then
  wget -c https://dl.fbaipublicfiles.com/parlai/empatheticdialogues/empatheticdialogues.tar.gz -O empatheticdialogues.tar.gz
fi
# Extract safely
if [ ! -d "empatheticdialogues" ]; then
  tar -xzf empatheticdialogues.tar.gz
fi
cd ..

# ------------------------------------------------------------
# 2) PsyDial (privacy-preserving long-term counseling dialogs)
# Paper + project repo; dataset/code hosted on GitHub
# ------------------------------------------------------------
log "⬇️ PsyDial (repo clone) ..."
cd pysdial
if [ ! -d "PsyDial" ]; then
  git clone https://github.com/qiuhuachuan/PsyDial.git
fi
cd ..

# ------------------------------------------------------------
# 3) MentalChat-16K (HF dataset)
# ------------------------------------------------------------
log "⬇️ MentalChat-16K (Hugging Face) ..."
cd mentalchat16k
# Prefer huggingface-cli if available; fallback to instruction
if command -v huggingface-cli >/dev/null 2>&1; then
  # This will create a local copy in the current directory
  huggingface-cli download ShenLab/MentalChat16K --local-dir . --repo-type dataset
else
  cat > HOW_TO_GET.txt <<'EOF'
MentalChat-16K requires Hugging Face CLI for convenient download.

Quick steps:
  pip install -U "huggingface_hub[cli]"
  huggingface-cli download ShenLab/MentalChat16K --local-dir . --repo-type dataset

Homepage:
  https://huggingface.co/datasets/ShenLab/MentalChat16K
Paper:
  https://arxiv.org/abs/2503.13509
EOF
fi
cd ..

# ------------------------------------------------------------
# 4) MEDIC (Multimodal Empathy in Psychotherapy)
# This often requires request/author approval. Create placeholder.
# ------------------------------------------------------------
log "📝 MEDIC requires access request (creating placeholder) ..."
cd medic
cat > READ_ME_FIRST.txt <<'EOF'
MEDIC (Multimodal Empathy in Counseling) dataset typically requires permission from authors.

Official page:
  https://ustc-ac.github.io/datasets/medic/

Request access as instructed on the page. Once granted, place files here.
EOF
cd ..

# ------------------------------------------------------------
# 5) Mental Health Counseling Conversations (HF)
# ------------------------------------------------------------
log "⬇️ Mental Health Counseling Conversations (Hugging Face) ..."
cd mh_counseling
if command -v huggingface-cli >/dev/null 2>&1; then
  huggingface-cli download Amod/mental_health_counseling_conversations --local-dir . --repo-type dataset
else
  cat > HOW_TO_GET.txt <<'EOF'
This dataset is hosted on Hugging Face.

Install CLI:
  pip install -U "huggingface_hub[cli]"

Download:
  huggingface-cli download Amod/mental_health_counseling_conversations --local-dir . --repo-type dataset

Card:
  https://huggingface.co/datasets/Amod/mental_health_counseling_conversations
EOF
fi
cd ..

# ------------------------------------------------------------
# 6) CounselChat (therapist Q&A)
# ------------------------------------------------------------
log "⬇️ CounselChat (GitHub repo) ..."
cd counselchat
if [ ! -d "counsel-chat" ]; then
  git clone https://github.com/nbertagnolli/counsel-chat.git
fi
# Attempt to fetch dataset from HF via the repo hint (optional manual step)
cat > OPTIONAL.txt <<'EOF'
CounselChat dataset is mirrored on Hugging Face as:
  nbertagnolli/counsel-chat

To pull via HF:
  huggingface-cli download nbertagnolli/counsel-chat --local-dir ./hf_mirror --repo-type dataset
EOF
cd ..

# ------------------------------------------------------------
# 7) ECC (Emotion–Cause Conversation)
# Paper + GitHub repo; pull the code/repo
# ------------------------------------------------------------
log "⬇️ ECC (Emotion–Cause Conversations) ..."
cd ecc
# Try to clone the repo referenced in the paper
if [ ! -d "ECC" ]; then
  git clone https://github.com/Yuan-23/ECC.git || true
fi
# Save the EMNLP paper PDF
if [ ! -f "ECC_paper_emnlp2025.pdf" ]; then
  wget -c https://aclanthology.org/2025.emnlp-main.306.pdf -O ECC_paper_emnlp2025.pdf
fi
cd ..

log "✅ All steps completed. Review ./logs/install.log for details."
``